style.css:
@-moz-document domain("discord.com") {
body {
    background-image: url(https://de.pinterest.com/pin/17803361022896448/);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
  }

  /* Makes Discord content background more transparent */
  .theme-dark, .appMount-3lHmkl {
    background: rgba(0, 0, 0, 0.6) !important;
  }

  /* Optional: Remove some backgrounds to make image more visible */
  .bg-1QIAus, .chatContent-3KubbW, .container-1NXEtd {
    background-color: transparent !important;
  }
}
